# Dicionário do Pregador — lote 2: nomes de Deus e mais palavras da pregação
L=[]
def E(pt,es,mpt,mes,orig,vs,apt=(),aes=()):L.append(dict(pt=pt,es=es,mpt=mpt,mes=mes,o=orig,v=vs,apt=list(apt),aes=list(aes)))
# ---- Nomes de Deus
E('El Shaddai','El Shaddai','Nome de Deus revelado a Abraão: "Deus Todo-Poderoso", aquele que tem poder para cumprir o que promete, mesmo quando parece impossível.','Nombre de Dios revelado a Abraham: "Dios Todopoderoso", el que tiene poder para cumplir lo que promete, aunque parezca imposible.',
 [('H7706','Shaddai: Todo-Poderoso, Onipotente. Alguns o ligam à ideia de "o Suficiente", aquele que basta.','Shaddai: Todopoderoso, Omnipotente. Algunos lo ligan a la idea de "el Suficiente", el que basta.'),('H410','El: Deus, o Poderoso.','El: Dios, el Poderoso.')],
 ['0.17.1','0.35.11','1.6.3','18.91.1'],['todo-poderoso','todo poderoso','shadai'],['todopoderoso','shadai'])
E('El Elyon','El Elyon','"Deus Altíssimo": o Deus acima de todos os deuses, reis e poderes. Assim Melquisedeque abençoou Abraão.','"Dios Altísimo": el Dios por encima de todos los dioses, reyes y poderes. Así Melquisedec bendijo a Abraham.',
 [('H5945','Elyon: Altíssimo, o mais alto, supremo.','Elyón: Altísimo, el más alto, supremo.')],['0.14.18','0.14.19','18.91.1','26.4.17'],['altissimo','altíssimo'],['altisimo','altísimo'])
E('El Olam','El Olam','"Deus Eterno": o Deus que não tem começo nem fim e é fiel para sempre.','"Dios Eterno": el Dios que no tiene principio ni fin y es fiel para siempre.',
 [('H5769','Olam: eternidade, tempo sem fim, para sempre.','Olam: eternidad, tiempo sin fin, para siempre.')],['0.21.33','22.40.28','18.90.2'],['deus eterno'],['dios eterno'])
E('Jeová-Jiré','Jehová-Jireh','"O Senhor proverá": nome dado por Abraão ao monte onde Deus providenciou o cordeiro no lugar de Isaque.','"Jehová proveerá": nombre dado por Abraham al monte donde Dios proveyó el cordero en lugar de Isaac.',
 [('H3070','Yehovah yireh: "o Senhor verá", isto é, "o Senhor proverá". Deus vê a necessidade antes e providencia.','Yehovah yiré: "Jehová verá", es decir, "Jehová proveerá". Dios ve la necesidad antes y provee.')],['0.22.14','0.22.8','49.4.19'],['jeova jire','jire','provera','proverá'],['jehova jireh','jireh','proveera','proveerá'])
E('Jeová-Rafá','Jehová-Rafa','"O Senhor que te sara": Deus se revelou como aquele que cura o corpo, a alma e a nação.','"Jehová tu sanador": Dios se reveló como el que sana el cuerpo, el alma y la nación.',
 [('H7495','Rafa: curar, sarar, restaurar, consertar o que está quebrado.','Rafá: sanar, curar, restaurar, reparar lo que está roto.')],['1.15.26','18.103.3','22.53.5','13.7.14'],['jeova rafa','rafa','que te sara'],['jehova rafa','rafa','sanador'])
E('Jeová-Nissi','Jehová-Nisi','"O Senhor é a minha bandeira": nome do altar de Moisés depois da vitória sobre Amaleque. A vitória vem do Senhor.','"Jehová es mi estandarte": nombre del altar de Moisés después de la victoria sobre Amalec. La victoria viene del Señor.',
 [('H3071','Yehovah nissi: "o Senhor é meu estandarte", a bandeira levantada que reúne o exército e anuncia a vitória.','Yehovah nisí: "Jehová es mi estandarte", la bandera levantada que reúne al ejército y anuncia la victoria.')],['1.17.15','21.2.4','22.11.10'],['jeova nissi','nissi','bandeira'],['jehova nisi','nisi','estandarte'])
E('Jeová-Shalom','Jehová-Shalom','"O Senhor é paz": nome do altar de Gideão quando Deus o chamou e lhe tirou o medo.','"Jehová es paz": nombre del altar de Gedeón cuando Dios lo llamó y le quitó el miedo.',
 [('H3073','Yehovah shalom: "o Senhor é paz", plenitude e bem-estar.','Yehovah shalom: "Jehová es paz", plenitud y bienestar.')],['6.6.24','22.26.3','42.14.27'],['jeova shalom'],['jehova shalom'])
E('Jeová-Tsidkenu','Jehová-Tsidkenu','"O Senhor, justiça nossa": nome profético do Messias, que nos dá a justiça que não temos.','"Jehová, justicia nuestra": nombre profético del Mesías, que nos da la justicia que no tenemos.',
 [('H3072','Yehovah tsidqenu: "o Senhor é a nossa justiça".','Yehovah tsidkenu: "Jehová es nuestra justicia".')],['23.23.6','23.33.16','46.5.21'],['jeova tsidkenu','tsidkenu','justica nossa'],['jehova tsidkenu','tsidkenu','justicia nuestra'])
E('Jeová-Shamá','Jehová-Sama','"O Senhor está ali": nome da cidade de Deus na visão de Ezequiel. Onde Deus está, ali está tudo.','"Jehová allí": nombre de la ciudad de Dios en la visión de Ezequiel. Donde Dios está, allí está todo.',
 [('H3074','Yehovah shammah: "o Senhor está ali".','Yehovah shamá: "Jehová está allí".')],['25.48.35','39.28.20','65.21.3'],['jeova shama','shama'],['jehova sama','sama'])
E('Senhor dos Exércitos','Señor de los Ejércitos','Título de Deus como comandante de todos os exércitos do céu e da terra. Ninguém pode vencê-lo.','Título de Dios como comandante de todos los ejércitos del cielo y de la tierra. Nadie lo puede vencer.',
 [('H6635','Tsaba: exército, hoste, multidão organizada para a guerra. "Senhor dos Exércitos" = YHWH Tsebaot.','Tsabá: ejército, hueste, multitud organizada para la guerra. "Jehová de los ejércitos" = YHWH Tsebaot.'),('G4519','Sabaōth: forma grega de "exércitos" (Rm 9:29; Tg 5:4).','Sabaoth: forma griega de "ejércitos" (Ro 9:29; Stg 5:4).')],
 ['8.17.45','22.6.3','18.46.7','58.5.4'],['sabaoth','jeova dos exercitos'],['sabaoth','jehova de los ejercitos'])
E('Pai','Padre','Deus é Pai: criou, cuida, corrige e ama seus filhos. Jesus nos ensinou a chamá-lo "Pai nosso".','Dios es Padre: creó, cuida, corrige y ama a sus hijos. Jesús nos enseñó a llamarlo "Padre nuestro".',
 [('H1','Av: pai, antepassado, fundador.','Av: padre, antepasado, fundador.'),('G3962','Patḗr: pai.','Patér: padre.'),('G5','Abbá: palavra aramaica de intimidade, como uma criança chama o pai: "Papai". Jesus a usou no Getsêmani (Mc 14:36).','Abbá: palabra aramea de intimidad, como un niño llama a su padre: "Papá". Jesús la usó en Getsemaní (Mr 14:36).')],
 ['39.6.9','44.8.15','47.4.6','40.14.36','18.103.13'],['aba','abba','pai nosso'],['abba','padre nuestro'])
E('Filho de Deus','Hijo de Dios','Título de Jesus que mostra que Ele tem a mesma natureza do Pai. Os que creem nele recebem o direito de ser filhos de Deus (Jo 1:12).','Título de Jesús que muestra que Él tiene la misma naturaleza del Padre. Los que creen en Él reciben el derecho de ser hijos de Dios (Jn 1:12).',
 [('G5207','Huiós: filho; aquele que tem a natureza e a herança do pai.','Huiós: hijo; el que tiene la naturaleza y la herencia del padre.')],['39.16.16','42.1.12','42.20.31','44.8.14'],['filho','filhos de deus'],['hijo','hijos de dios'])
E('Cordeiro de Deus','Cordero de Dios','Jesus, o sacrifício perfeito oferecido por Deus para tirar o pecado do mundo, como o cordeiro da Páscoa.','Jesús, el sacrificio perfecto ofrecido por Dios para quitar el pecado del mundo, como el cordero de la Pascua.',
 [('G286','Amnós: cordeiro, especialmente o de sacrifício. "Eis o Cordeiro de Deus" (Jo 1:29).','Amnós: cordero, especialmente el de sacrificio. "He aquí el Cordero de Dios" (Jn 1:29).'),('G721','Arníon: cordeirinho; título de Jesus em Apocalipse.','Arníon: corderito; título de Jesús en Apocalipsis.'),('H7716','Seh: cordeiro, ovelha ou cabrito; "Deus proverá para si o cordeiro" (Gn 22:8).','Seh: cordero, oveja o cabrito; "Dios se proveerá de cordero" (Gn 22:8).')],
 ['42.1.29','22.53.7','59.1.19','65.5.12','0.22.8'],['cordeiro'],['cordero'])
E('Nome','Nombre','Na Bíblia o nome revela a pessoa e sua autoridade. Orar e agir "em nome de Jesus" é agir pela autoridade dele.','En la Biblia el nombre revela a la persona y su autoridad. Orar y actuar "en el nombre de Jesús" es actuar por su autoridad.',
 [('H8034','Shem: nome, reputação, caráter, fama.','Shem: nombre, reputación, carácter, fama.'),('G3686','Ónoma: nome, autoridade, caráter.','Ónoma: nombre, autoridad, carácter.')],['19.18.10','49.2.9','42.14.13','43.4.12'],['nome de jesus'],['nombre de jesus'])
E('Mundo','Mundo','Pode ser a criação, a humanidade que Deus ama, ou o sistema que vive longe de Deus e ao qual o crente não deve se conformar.','Puede ser la creación, la humanidad que Dios ama, o el sistema que vive lejos de Dios y al cual el creyente no debe conformarse.',
 [('G2889','Kósmos: ordem, arranjo; o mundo, a humanidade ou o sistema contrário a Deus (Jo 3:16; 1 Jo 2:15).','Kósmos: orden, arreglo; el mundo, la humanidad o el sistema contrario a Dios (Jn 3:16; 1 Jn 2:15).'),('G165','Aiṓn: era, século, época. "Não vos conformeis com este século" (Rm 12:2).','Aión: era, siglo, época. "No os conforméis a este siglo" (Ro 12:2).')],
 ['42.3.16','61.2.15','44.12.2','42.16.33'],['seculo','século'],['siglo'])
E('Carne','Carne','O corpo humano e, nas cartas de Paulo, a natureza humana inclinada ao pecado, que luta contra o Espírito.','El cuerpo humano y, en las cartas de Pablo, la naturaleza humana inclinada al pecado, que lucha contra el Espíritu.',
 [('H1320','Basar: carne, corpo, ser humano frágil.','Basar: carne, cuerpo, ser humano frágil.'),('G4561','Sárx: carne; a natureza humana fraca e pecaminosa (Gl 5:17).','Sarx: carne; la naturaleza humana débil y pecaminosa (Gá 5:17).')],
 ['47.5.16','47.5.17','44.8.5','42.1.14'],['natureza carnal','carnal'],['naturaleza carnal','carnal'])
E('Tentação','Tentación','Prova ou incitação ao pecado. Deus permite provas para fortalecer a fé, mas não tenta ninguém para o mal; e sempre dá a saída (1 Co 10:13).','Prueba o incitación al pecado. Dios permite pruebas para fortalecer la fe, pero no tienta a nadie al mal; y siempre da la salida (1 Co 10:13).',
 [('G3986','Peirasmós: prova, provação, tentação.','Peirasmós: prueba, tribulación, tentación.'),('G3985','Peirázō: provar, testar, tentar.','Peirázo: probar, examinar, tentar.'),('H5254','Nasah: provar, testar. "Deus provou Abraão" (Gn 22:1).','Nasá: probar, poner a prueba. "Probó Dios a Abraham" (Gn 22:1).')],
 ['45.10.13','58.1.12','58.1.13','39.4.1','39.6.13'],['provacao','provação','prova','tentar'],['prueba','tentar'])
E('Satanás','Satanás','O adversário de Deus e do seu povo, que acusa, engana e tenta. Já foi vencido por Cristo na cruz.','El adversario de Dios y de su pueblo, que acusa, engaña y tienta. Ya fue vencido por Cristo en la cruz.',
 [('H7854','Satan: adversário, opositor, acusador.','Satán: adversario, opositor, acusador.'),('G1228','Diábolos: acusador, caluniador, aquele que divide. Daí "diabo".','Diábolos: acusador, calumniador, el que divide. De ahí "diablo".'),('G4567','Satanâs: forma grega de Satanás.','Satanás: forma griega de Satanás.')],
 ['17.1.6','39.4.10','58.4.7','65.12.10','61.3.8'],['diabo','inimigo','adversario','diabolos'],['diablo','enemigo','adversario'])
E('Demônio','Demonio','Espíritos malignos sob o domínio de Satanás. Jesus os expulsava com autoridade e deu essa autoridade aos discípulos.','Espíritus malignos bajo el dominio de Satanás. Jesús los expulsaba con autoridad y dio esa autoridad a los discípulos.',
 [('G1140','Daimónion: demônio, espírito maligno.','Daimónion: demonio, espíritu maligno.')],['41.10.17','40.16.17','58.2.19'],['demonios','demônios','espiritos malignos','libertacao'],['demonios','espiritus malignos'])
E('Anjo','Ángel','Seres espirituais criados por Deus, mensageiros e servidores enviados para ajudar os que herdarão a salvação (Hb 1:14).','Seres espirituales creados por Dios, mensajeros y servidores enviados para ayudar a los que serán herederos de la salvación (He 1:14).',
 [('H4397','Mal’akh: mensageiro, enviado; usado para anjos e para mensageiros humanos.','Mal’aj: mensajero, enviado; usado para ángeles y para mensajeros humanos.'),('G32','Ángelos: mensageiro, anjo.','Ángelos: mensajero, ángel.')],
 ['57.1.14','18.91.11','41.2.10','43.12.7'],['anjos','arcanjo','querubim','serafim'],['angeles','ángeles','arcangel','querubin','serafin'])
E('Inferno','Infierno','O lugar dos mortos e do castigo eterno dos que rejeitam a Deus. Jesus falou dele como alerta, por amor.','El lugar de los muertos y del castigo eterno de los que rechazan a Dios. Jesús habló de él como advertencia, por amor.',
 [('H7585','Sheol: a sepultura, o mundo dos mortos.','Seol: el sepulcro, el mundo de los muertos.'),('G86','Hádēs: o lugar dos mortos (equivale ao Sheol).','Hades: el lugar de los muertos (equivale al Seol).'),('G1067','Géenna: o vale de Hinom, fora de Jerusalém, onde se queimava lixo; imagem do castigo eterno.','Gehena: el valle de Hinom, fuera de Jerusalén, donde se quemaba basura; imagen del castigo eterno.')],
 ['39.10.28','41.16.23','65.20.14','18.16.10'],['sheol','hades','geena','lago de fogo'],['seol','hades','gehena','lago de fuego'])
E('Morte','Muerte','Separação: do corpo e da alma (morte física) e do ser humano e Deus (morte espiritual). Cristo venceu a morte.','Separación: del cuerpo y el alma (muerte física) y del ser humano y Dios (muerte espiritual). Cristo venció la muerte.',
 [('H4194','Mavet: morte.','Mávet: muerte.'),('G2288','Thánatos: morte. "O salário do pecado é a morte" (Rm 6:23).','Thánatos: muerte. "La paga del pecado es muerte" (Ro 6:23).')],['44.6.23','45.15.55','57.2.14','18.23.4'],['morrer'],['morir'])
E('Juízo','Juicio','Deus é o Juiz justo. Haverá um dia em que todos prestarão contas; em Cristo, o crente não entra em condenação (Jo 5:24).','Dios es el Juez justo. Habrá un día en que todos rendirán cuentas; en Cristo, el creyente no vendrá a condenación (Jn 5:24).',
 [('H4941','Mishpat: juízo, justiça, direito, decisão do juiz.','Mishpat: juicio, justicia, derecho, decisión del juez.'),('G2920','Krísis: juízo, julgamento, decisão. Daí a palavra "crise".','Krísis: juicio, decisión. De ahí la palabra "crisis".')],
 ['42.5.24','57.9.27','46.5.10','29.5.24'],['julgamento','juiz','condenacao'],['juez','condenacion'])
E('Eternidade','Eternidad','O que não tem fim. Deus é eterno, e dá vida eterna aos que creem em Jesus.','Lo que no tiene fin. Dios es eterno, y da vida eterna a los que creen en Jesús.',
 [('H5769','Olam: tempo muito longo, eternidade, para sempre.','Olam: tiempo muy largo, eternidad, para siempre.'),('G166','Aiṓnios: eterno, que dura para sempre. "Vida eterna" (Jo 3:16).','Aiónios: eterno, que dura para siempre. "Vida eterna" (Jn 3:16).')],
 ['20.3.11','42.3.16','42.17.3','18.90.2'],['eterno'],['eterno'])
E('Novo nascimento','Nuevo nacimiento','A obra do Espírito Santo que dá uma vida nova a quem crê em Jesus. "Necessário vos é nascer de novo" (Jo 3:7).','La obra del Espíritu Santo que da una vida nueva a quien cree en Jesús. "Os es necesario nacer de nuevo" (Jn 3:7).',
 [('G509','Ánōthen: de novo e também "do alto". Nascer de novo é nascer de cima, de Deus.','Ánothen: de nuevo y también "de arriba". Nacer de nuevo es nacer de lo alto, de Dios.'),('G1080','Gennáō: gerar, nascer.','Gennáo: engendrar, nacer.'),('G3824','Palingenesía: regeneração, novo começo (Tt 3:5).','Palingenesía: regeneración, nuevo comienzo (Tit 3:5).')],
 ['42.3.3','42.3.7','55.3.5','59.1.23','46.5.17'],['nascer de novo','regeneracao','regeneração','nova criatura'],['nacer de nuevo','regeneracion','regeneración','nueva criatura'])
E('Conversão','Conversión','Voltar-se do pecado para Deus, pela fé em Cristo. É o início visível da vida cristã.','Volverse del pecado a Dios, por la fe en Cristo. Es el inicio visible de la vida cristiana.',
 [('G1994','Epistréphō: voltar-se, dar meia-volta. "Convertei-vos para que sejam apagados os vossos pecados" (At 3:19).','Epistréfo: volverse, dar media vuelta. "Convertíos, para que sean borrados vuestros pecados" (Hch 3:19).'),('H7725','Shuv: voltar, retornar.','Shuv: volver, regresar.')],
 ['43.3.19','39.18.3','51.1.9'],['converter'],['convertir'])
E('Justificação','Justificación','Ato de Deus que declara justo o pecador que crê em Jesus, não por mérito próprio, mas pela obra de Cristo.','Acto de Dios que declara justo al pecador que cree en Jesús, no por mérito propio, sino por la obra de Cristo.',
 [('G1344','Dikaióō: declarar justo, absolver no tribunal.','Dikaióo: declarar justo, absolver en el tribunal.'),('G1347','Dikaíōsis: justificação, absolvição (Rm 4:25).','Dikaíosis: justificación, absolución (Ro 4:25).')],
 ['44.5.1','44.3.24','47.2.16','44.4.25'],['justificar','justificado'],['justificar','justificado'])
E('Reconciliação','Reconciliación','Deus restaura a amizade com o ser humano por meio de Cristo, e nos dá o ministério de reconciliar outros com Ele.','Dios restaura la amistad con el ser humano por medio de Cristo, y nos da el ministerio de reconciliar a otros con Él.',
 [('G2643','Katallagḗ: reconciliação, troca de inimizade por amizade.','Katallagé: reconciliación, cambio de enemistad por amistad.'),('G2644','Katallássō: reconciliar.','Katallásso: reconciliar.')],['46.5.18','46.5.19','46.5.20','44.5.10'],['reconciliar'],['reconciliar'])
E('Propiciação','Propiciación','Jesus é o sacrifício que satisfaz a justiça de Deus e remove a sua ira contra o pecado.','Jesús es el sacrificio que satisface la justicia de Dios y quita su ira contra el pecado.',
 [('G2435','Hilastḗrion: propiciatório, a tampa da arca onde se aspergia o sangue (Hb 9:5); Cristo é o nosso propiciatório (Rm 3:25).','Hilastérion: propiciatorio, la tapa del arca donde se rociaba la sangre (He 9:5); Cristo es nuestro propiciatorio (Ro 3:25).'),('G2434','Hilasmós: propiciação (1 Jo 2:2).','Hilasmós: propiciación (1 Jn 2:2).'),('H3722','Kafar: cobrir, expiar, fazer expiação. Daí Yom Kippur, o Dia da Expiação.','Kafar: cubrir, expiar, hacer expiación. De ahí Yom Kipur, el Día de la Expiación.')],
 ['44.3.25','61.2.2','61.4.10','2.16.30'],['expiacao','expiação','propiciatorio'],['expiacion','expiación','propiciatorio'])
E('Eleição','Elección','Deus escolhe por graça um povo para si, para salvação e para servi-lo. É motivo de gratidão e humildade.','Dios escoge por gracia un pueblo para sí, para salvación y para servirle. Es motivo de gratitud y humildad.',
 [('G1589','Eklogḗ: escolha, eleição.','Eklogé: elección, escogimiento.'),('G1588','Eklektós: escolhido, eleito.','Eklektós: escogido, elegido.'),('H972','Bachir: escolhido. "O meu escolhido, em quem a minha alma se compraz" (Is 42:1).','Bajir: escogido. "Mi escogido, en quien mi alma tiene contentamiento" (Is 42:1).')],
 ['48.1.4','59.2.9','44.8.33','22.42.1'],['eleito','escolhido'],['elegido','escogido','eleccion'])
E('Obediência','Obediencia','Ouvir a Deus e fazer o que Ele diz. Para Deus, obedecer é melhor do que sacrificar (1 Sm 15:22).','Oír a Dios y hacer lo que Él dice. Para Dios, obedecer es mejor que los sacrificios (1 S 15:22).',
 [('H8085','Shama: ouvir, escutar e obedecer. "Ouve, Israel" (Shemá Israel, Dt 6:4).','Shamá: oír, escuchar y obedecer. "Oye, Israel" (Shemá Israel, Dt 6:4).'),('G5218','Hypakoḗ: obediência; literalmente "ouvir debaixo de", submeter-se ao que se ouve.','Hypakoé: obediencia; literalmente "oír debajo de", someterse a lo que se oye.')],
 ['8.15.22','4.6.4','42.14.15','49.2.8'],['obedecer','ouvir'],['obedecer','oir'])
E('Temor do Senhor','Temor de Jehová','Reverência profunda diante da grandeza e santidade de Deus, que leva a amá-lo, obedecê-lo e afastar-se do mal. É o princípio da sabedoria.','Reverencia profunda ante la grandeza y santidad de Dios, que lleva a amarlo, obedecerlo y apartarse del mal. Es el principio de la sabiduría.',
 [('H3374','Yirah: temor, reverência, respeito profundo.','Yirá: temor, reverencia, respeto profundo.'),('G5401','Phóbos: medo, temor, reverência. Daí "fobia".','Fóbos: miedo, temor, reverencia. De ahí "fobia".')],
 ['19.1.7','19.9.10','18.111.10','49.2.12'],['temor','temor de deus','reverencia'],['temor','temor de dios','reverencia'])
E('Sabedoria','Sabiduría','Mais que conhecimento: é saber viver de acordo com Deus nas decisões do dia a dia. Deus a dá a quem pede (Tg 1:5).','Más que conocimiento: es saber vivir de acuerdo con Dios en las decisiones del día a día. Dios la da a quien la pide (Stg 1:5).',
 [('H2451','Chokmah: sabedoria, habilidade prática, competência para viver bem.','Jokmá: sabiduría, habilidad práctica, competencia para vivir bien.'),('G4678','Sophía: sabedoria. Cristo é a sabedoria de Deus (1 Co 1:24).','Sofía: sabiduría. Cristo es la sabiduría de Dios (1 Co 1:24).')],
 ['19.1.7','19.9.10','58.1.5','45.1.24'],['sabio','sábio'],['sabio'])
